  const updated = await memberRepo.updateMemberRole('"''').replace('    to: updated.role,','    to: updated.role,\\n    active: member.status === \"active\",').replace('    userId: removed.userId,','    userId: removed.userId,\\n    role: member.role,\\n    active: member.status === \"active\",'); p.write_text(s)
