p=Path('src/app/(dashboard)/[orgSlug]/settings/members/page.tsx'); s=p.read_text().replace('{members.total} of {limits.seats} seats used', '{seats.used} of {limits.seats} seats used'); p.write_text(s)
p=Path('src/server/db/seed.ts'); s=p.read_text().replace('seatsUsed: seededUsers.length','seatsUsed: ROLE_SPECS.filter((spec) => spec.role "'!== "viewer").length'"'); p.write_text(s)
