p=Path('tests/server/plan-limits.test.ts'); s=p.read_text().replace('      used: 4,','      used: 3,'); p.write_text(s)
p=Path('tests/services/invitation-service.test.ts'); s=p.read_text().replace('already seeds 4 active\\n    // members (owner, admin, member, viewer), so the org starts over quota.', 'already seeds 3 billable active\\n    // members (owner, admin, member), so the org starts at quota.').replace('4 from createTenant, 5 more','3 from createTenant, 6 more').replace('i < 5; i += 1','i < 6; i += 1').replace('countActiveMembers(tenant.org.id)).resolves.toBe(9)', 'countBillableActiveMembers(tenant.org.id)).resolves.toBe(9)'); p.write_text(s)
